    { id: "bladderwrack", type: "superfood", name: "Bladderwrack", color: "green", image: "/images/savage/bladderwrack_seaweed.webp", benefit: "Detox & Cleansing", teaser: "The Iodine-Rich Sea Herb", nutrients: ["Iodine", "Fucoidan", "Alginic Acid"], synergy: "Always pair with Sea Moss.", tips: "Fucoidan from bladderwrack has demonstrated antiviral, anti-tumor, and anticoagulant properties across multiple lines of research, making it one of the most bioactive compounds in marine algae.", "mainBenefits": [{"title": "Fucoidan Antiviral and Anti-Tumor", "description": "Fucoidan has demonstrated antiviral, anti-tumor, and anticoagulant properties in multiple research lines, making it one of the most bioactive compounds in all of marine algae."}, {"title": "Thyroid and Iodine Support", "description": "Rich in iodine essential for thyroid hormone synthesis, supporting metabolic rate, energy production, and the hormonal regulation that governs nearly every body system."}, {"title": "Alginic Acid Gut Detox", "description": "Alginic acid binds to heavy metals and radioactive elements in the gut, facilitating their elimination before absorption — providing a unique marine-derived detoxification mechanism."}, {"title": "Anti-Inflammatory Marine Polyphenols", "description": "Phlorotannins unique to brown algae provide potent anti-inflammatory protection, reducing systemic inflammation linked to chronic disease and metabolic disorders."}] },
    { id: "maqui_berry", type: "superfood", name: "Maqui Berry", color: "purple", image: "/images/savage/maqui_berry.webp", benefit: "Antioxidant Power", teaser: "The World's Most Antioxidant Berry", nutrients: ["Delphinidins", "Anthocyanins", "Vitamin C"], synergy: "Pair with Acai for max antioxidant punch.", tips: "Delphinidins — the rarest and most potent subclass of anthocyanins — are found in exceptional concentrations in maqui berry, giving it superior anti-inflammatory capacity over most other berries.", "mainBenefits": [{"title": "Delphinidins — Rarest Anthocyanins", "description": "Delphinidins are the rarest and most potent subclass of anthocyanins, found in exceptional concentrations in maqui berry — giving it superior anti-inflammatory capacity over most other berries."}, {"title": "Blood Sugar and Insulin Regulation", "description": "Delphinidins specifically inhibit an enzyme involved in carbohydrate digestion, reducing post-meal glucose spikes and improving insulin sensitivity with regular use."}, {"title": "Antioxidant Supremacy", "description": "Consistently ranks among the highest ORAC (antioxidant capacity) scores of any known fruit, providing extraordinary cellular protection from free radical damage."}, {"title": "Eye Health and Tear Film Support", "description": "Unique compounds in maqui berry have been studied for reducing eye dryness and improving tear film stability — offering benefits for screen-related eye fatigue and dry eye syndrome."}] },
    { id: "mesquite", type: "superfood", name: "Mesquite", color: "yellow", image: "/images/savage/mesquite_powder.webp", benefit: "Energy & Vitality", teaser: "The Desert Protein Pod", nutrients: ["Protein", "Lysine", "Fiber"], synergy: "Pair with Cacao for a caramel-like boost.", tips: "Mesquite's lysine content supplements the amino acid most commonly deficient in grain-heavy diets, completing the protein profile of plant-based meals.", "mainBenefits": [{"title": "Lysine for Complete Protein Profiles", "description": "Rich in lysine — the amino acid most deficient in grain-heavy diets — completing the protein profile of plant-based meals and supporting collagen synthesis throughout the body."}, {"title": "Low Glycemic Sustained Energy", "description": "Natural sugars bound in fiber provide slow-release energy with minimal glycemic impact, making mesquite an excellent natural sweetener for blood sugar management."}, {"title": "Gut Prebiotic Support", "description": "Soluble fiber feeds beneficial gut bacteria and supports bowel regularity, contributing to a healthy microbiome and the immune benefits that follow from it."}, {"title": "Mineral Density", "description": "Contains calcium, magnesium, potassium, iron, and zinc, providing a meaningful multi-mineral contribution from a natural whole-food sweetener."}] },
    { id: "pine_pollen", type: "superfood", name: "Pine Pollen", color: "yellow", image: "/images/savage/pine_pollen_powder.webp", benefit: "Brain & Memory", teaser: "Nature's Testosterone Booster", nutrients: ["Phyto-Androgens", "DHEA", "Amino Acids"], synergy: "Pair with Ashwagandha.", tips: "Pine pollen contains phyto-androgens including DHEA, which support testosterone precursor production and hormonal vitality — rare compounds in the plant kingdom.", "mainBenefits": [{"title": "Phyto-Androgen Hormonal Support", "description": "Contains DHEA and other phyto-androgens that support testosterone precursor production in men, offering natural hormonal vitality support rare in the plant kingdom."}, {"title": "Complete Nutritional Profile", "description": "One of nature's most complete foods, containing over 200 bioactive nutrients including vitamins, minerals, amino acids, enzymes, and antioxidants in a single source."}, {"title": "Immune System Activation", "description": "Polysaccharides and flavonoids activate immune cells and provide antioxidant protection, supporting the body's defenses against pathogens and cellular stress."}, {"title": "Anti-Aging Antioxidants", "description": "SOD and other antioxidant enzymes help neutralize free radicals and reduce oxidative aging, contributing to cellular longevity with consistent use."}] },
    { id: "psyllium", type: "superfood", name: "Psyllium", color: "green", image: "/images/savage/psyllium.webp", benefit: "Detox & Cleansing", teaser: "The Gut Broom", nutrients: ["Soluble Fiber", "Psyllium Husk", "Mucilage"], synergy: "Always take with plenty of water.", tips: "Psyllium's mucilage forms a dense gel in the gut that simultaneously feeds beneficial bacteria, slows glucose absorption, and physically traps cholesterol for excretion.", "mainBenefits": [{"title": "Cholesterol Gel Trap", "description": "Mucilage forms a dense cholesterol-trapping gel in the gut that physically prevents LDL absorption, providing clinically validated cholesterol reduction with regular use."}, {"title": "Blood Sugar Slowing Mechanism", "description": "Gel matrix slows glucose digestion and absorption from the entire meal, reducing post-meal blood sugar spikes and improving glycemic control in diabetic and pre-diabetic individuals."}, {"title": "Prebiotic Gut Fermentation", "description": "Fermented by beneficial bacteria to produce short-chain fatty acids including butyrate, which heals the gut lining and reduces the intestinal inflammation driving IBS and leaky gut."}, {"title": "Bowel Regularity — Both Directions", "description": "Uniquely effective for both constipation and diarrhea — the gel absorbs excess water in loose stools while lubricating and softening compacted ones."}] },
    { id: "saffron", type: "superfood", name: "Saffron", color: "yellow", image: "/images/savage/saffron.webp", benefit: "Brain & Memory", teaser: "The Golden Mood Lifter", nutrients: ["Crocin", "Safranal", "Kaempferol"], synergy: "Pair with Turmeric for anti-inflammatory synergy.", tips: "Crocin in saffron inhibits serotonin reuptake with an efficacy comparable to certain antidepressants in clinical trials, positioning it as one of the most studied natural mood elevators.", "mainBenefits": [{"title": "Serotonin Reuptake Inhibition", "description": "Crocin inhibits serotonin reuptake with efficacy comparable to certain antidepressants in clinical trials, positioning saffron as one of the most studied natural mood elevators."}, {"title": "Anti-Depressant and Anxiolytic", "description": "Multiple randomized controlled trials confirm saffron reduces symptoms of mild-to-moderate depression and anxiety with a safety profile superior to pharmaceutical alternatives."}, {"title": "Memory and Cognitive Protection", "description": "Crocin and safranal protect neurons from oxidative damage and improve memory consolidation, with studies showing benefits for age-related cognitive decline and Alzheimer's prevention."}, {"title": "Appetite Regulation", "description": "Safranal reduces appetite and snacking behavior by modulating serotonin pathways, with clinical trials showing measurable reductions in between-meal caloric intake."}] },
    { id: "schisandra", type: "superfood", name: "Schisandra", color: "red", image: "/images/savage/schisandra_berries.webp", benefit: "Energy & Vitality", teaser: "The Five-Flavor Berry Adaptogen", nutrients: ["Schisandrin", "Lignans", "Vitamin C"], synergy: "Pair with Ashwagandha for stress resilience.", tips: "Schisandrin B protects liver cells from chemical damage while stimulating the liver's own detoxification enzyme systems — a dual protective and regenerative effect rare in single compounds.", "mainBenefits": [{"title": "Liver Protection and Regeneration", "description": "Schisandrin B protects liver cells from chemical and oxidative damage while stimulating the liver's own detoxification enzymes — a dual protective and regenerative effect rare in single compounds."}, {"title": "Five-Flavor Adaptogenic Balance", "description": "The only food containing all five flavors simultaneously, each activating different organ systems in Traditional Chinese Medicine — supporting whole-body energetic balance and resilience."}, {"title": "Cortisol and Stress Modulation", "description": "Reduces cortisol and adrenaline spikes from mental and physical stress, supporting adrenal health and improving the body's stress response with consistent adaptogenic use."}, {"title": "Mental Performance Under Pressure", "description": "Improves working memory, concentration, and mental endurance under stress — making schisandra particularly valuable during periods of high cognitive demand or physical fatigue."}] },
    { id: "tremella", type: "superfood", name: "Tremella", color: "yellow", image: "/images/savage/tremella_mushroom.webp", benefit: "Skin Glow & Beauty", teaser: "The Beauty Mushroom", nutrients: ["Polysaccharides", "Vitamin D", "Glucuronoxylomannan"], synergy: "Pair with Collagen for maximum skin hydration.", tips: "Tremella polysaccharides hold many times their weight in water at the cellular level, providing deep hydration from within that rivals hyaluronic acid for skin moisture retention.", "mainBenefits": [{"title": "Hyaluronic Acid-Like Skin Hydration", "description": "Tremella polysaccharides hold many times their weight in water at the cellular level, providing deep skin hydration from within that rivals hyaluronic acid for moisture retention."}, {"title": "Collagen Synthesis Support", "description": "Stimulates fibroblast activity and collagen production in the skin, reducing the appearance of fine lines and supporting long-term skin firmness and elasticity."}, {"title": "Neuroprotective Properties", "description": "Polysaccharides demonstrate neuroprotective effects and support NGF production, potentially slowing age-related cognitive decline and protecting neural tissue over time."}, {"title": "Immune and Anti-Inflammatory", "description": "Beta-glucans modulate the immune response and reduce chronic inflammation, supporting both immune defense and the reduction of inflammation-driven skin aging."}] }
